<script>
/* === KEYBOARD NAVIGATION === */
const slides = [...document.querySelectorAll('.slide')];
function currentIndex() {
  const y = window.scrollY;
  return Math.round(y / window.innerHeight);
}
function go(delta) {
  const idx = Math.max(0, Math.min(slides.length - 1, currentIndex() + delta));
  slides[idx].scrollIntoView({ behavior: 'smooth', block: 'start' });
}
document.addEventListener('keydown', (event) => {
  if (['ArrowRight', 'ArrowDown', ' ', 'PageDown'].includes(event.key)) { event.preventDefault(); go(1); }
  if (['ArrowLeft', 'ArrowUp', 'PageUp'].includes(event.key)) { event.preventDefault(); go(-1); }
});

/* === ACTIVE DOT STATE === */
const dots = [...document.querySelectorAll('.progress a')];
const observer = new IntersectionObserver(entries => {
  entries.forEach(entry => {
    if (entry.isIntersecting) {
      const idx = slides.indexOf(entry.target);
      dots.forEach((dot, dotIndex) => dot.style.background = dotIndex === idx ? 'var(--cyan)' : 'rgba(255,255,255,0.22)');
    }
  });
}, { threshold: 0.6 });
slides.forEach(slide => observer.observe(slide));
</script>
